user_input:
what does this do?

// ==UserScript==
// @name         Mastodon/Mas.to
// @description  
// @namespace    https://example.com/
// @version      2
// @author       Your Name
// @match        https://www.thecoli.com/threads/*
// @match        https://thecoli.com/threads/*
// @grant        GM_xmlhttpRequest
// ==/UserScript==

(function() {
    'use strict';

    var links = document.getElementsByTagName('a');
    for (var i = 0; i < links.length; i++) {
        var link = links[i];
        var href = link.href;
        if (href.includes('mastodon.social') || href.includes('mas.to')) {
            GM_xmlhttpRequest({
                method: "GET",
                url: href,
                onload: function(response) {
                    var parser = new DOMParser();
                    var htmlDoc = parser.parseFromString(response.responseText, "text/html");
                    var postWrapper = htmlDoc.querySelector('.focusable.detailed-status__wrapper');
                    if (postWrapper !== null) {
                        var postHTML = postWrapper.outerHTML;
                        var embed = '<iframe class="mastodon-embed" srcdoc=\'' + postHTML + '\' frameborder="0"></iframe>';
                        link.innerHTML = embed;
                    }
                }
            });
        }
    }
})();

